205	// TestExecuteExactRemainingAndOverflowBeforeInsufficient：端到端验证
206	// “恰好等于余额可成功”与“溢出先于不足报告”，失败不留任何资金变动/凭据/状态。
207	func TestExecuteExactRemainingAndOverflowBeforeInsufficient(t *testing.T) {
