263	// TestReceiptBalanceFieldsMustBePresent：凭据每项动作的四个余额字段
264	// （资金库/收款账户 × before/after）都必须明确写出。任何一侧任一字段缺失、
265	// 为 null 或类型不符——包括按转账金额推算本来应为 0 的字段——都判整份状态
266	// 损坏，错误指出提案编号、动作下标（0 起）、所在侧与字段名；不能根据转账
267	// 金额、账户余额或其它凭据补出。明确写出的整数 0 是合法记录，照常可读。
268	func TestReceiptBalanceFieldsMustBePresent(t *testing.T) {
269		dir := t.TempDir()
