283		if _, err := store.CastVote("gip-vote", "alice", true, 150); err != nil {
284			t.Fatal(err)
285		}
286		if _, err := store.CastVote("gip-vote", "dave", true, 150); err != nil {
287			t.Fatal(err)
288		}
