290			t.Fatal(err)
291		}
292		if _, err := store.Execute("gip-vote", 300); err != nil {
293			t.Fatal(err)
294		}
295		if err := store.Close(); err != nil {
296			t.Fatal(err)
297		}
298	
299		good, err := os.ReadFile(path)
300		if err != nil {
301			t.Fatal(err)
302		}
303	
304		// 基线：明确写出 0 的完整凭据照常可读，查询与执行重试行为不变。
305		t.Run("baseline readable with explicit zeros", func(t *testing.T) {
306			s, err := Open(path)
307			if err != nil {
308				t.Fatalf("reopen: %v", err)
309			}
310			defer s.Close()
311			r, ok, err := s.Receipt("gip-1")
312			if err != nil || !ok {
313				t.Fatalf("Receipt(gip-1) ok=%v err=%v", ok, err)
314			}
315			want := []struct{ tb, ta, rb, ra int64 }{
316				{400, 250, 0, 150},
317				{250, 100, 150, 300}, // 同一账户连续收款，承接上一笔结果
318			}
319			for i, w := range want {
