321				if ar.Treasury.Before != w.tb || ar.Treasury.After != w.ta ||
322					ar.Recipient.Before != w.rb || ar.Recipient.After != w.ra {
323					t.Fatalf("action %d = %+v, want treasury %d->%d recipient %d->%d",
324						i, ar, w.tb, w.ta, w.rb, w.ra)
325				}
326			}
327			// 投票凭据：资金库 100->0、收款账户 0->100，两个明确写出的 0。
328			vr, ok, err := s.Receipt("gip-vote")
329			if err != nil || !ok {
330				t.Fatalf("Receipt(gip-vote) ok=%v err=%v", ok, err)
331			}
332			if va := vr.Actions[0]; va.Treasury.Before != 100 || va.Treasury.After != 0 ||
333				va.Recipient.Before != 0 || va.Recipient.After != 100 {
334				t.Fatalf("unexpected vote action receipt: %+v", va)
335			}
336			if bal, _ := s.TreasuryBalance(); bal != 0 {
337				t.Fatalf("treasury = %d, want 0", bal)
338			}
339			if bal, _ := s.Balance("new"); bal != 300 {
