348		// mutateReceipt 改写第 ri 张凭据第 ai 个动作的余额字段；
349		// value 为 nil 时删除该字段（模拟缺损凭据）。
350		mutateReceipt := func(ri, ai int, side, field string, value any) []byte {
351			var doc map[string]any
352			if err := json.Unmarshal(good, &doc); err != nil {
353				t.Fatal(err)
354			}
355			entry := doc["receipts"].([]any)[ri].(map[string]any)["actions"].([]any)[ai].(map[string]any)[side].(map[string]any)
356			if value == nil {
357				delete(entry, field)
358			} else {
359				entry[field] = value
360			}
361			raw, err := json.MarshalIndent(doc, "", "  ")
362			if err != nil {
363				t.Fatal(err)
364			}
365			return append(raw, '\n')
366		}
367	
368		corruptions := []struct {
369			name string
370			raw  []byte
371			want []string
372		}{
373			// 任务示例：删除资金库侧的 after（本来应为 0）必须拒绝；
374			// 投票通过提案的凭据与登记提案适用同一规则。
375			{"treasury after missing (would be 0)", mutateReceipt(1, 0, "treasury", "after", nil),
376				[]string{`"gip-vote"`, "action 0", "treasury", `"after"`, "missing"}},
377			// 任务示例：删除收款账户侧的 before（本来应为 0）必须拒绝。
378			{"recipient before missing (would be 0)", mutateReceipt(0, 0, "recipient", "before", nil),
379				[]string{`"gip-1"`, "action 0", "recipient", `"before"`, "missing"}},
380			// 非零字段缺失适用同一规则。
381			{"treasury before missing (non-zero)", mutateReceipt(0, 0, "treasury", "before", nil),
382				[]string{`"gip-1"`, "action 0", "treasury", `"before"`, "missing"}},
383			{"recipient after missing (non-zero)", mutateReceipt(0, 1, "recipient", "after", nil),
384				[]string{`"gip-1"`, "action 1", "recipient", `"after"`, "missing"}},
385			// null 与类型不符同样不得折叠成 0。
386			{"treasury after null", mutateReceipt(0, 1, "treasury", "after", json.RawMessage("null")),
387				[]string{`"gip-1"`, "action 1", "treasury", `"after"`, "null"}},
388			{"recipient before wrong type", mutateReceipt(0, 0, "recipient", "before", "0"),
389				[]string{`"gip-1"`, "action 0", "recipient", `"before"`, "wrong type"}},
390			// 投票凭据的收款侧同样适用。
391			{"vote receipt recipient after missing", mutateReceipt(1, 0, "recipient", "after", nil),
392				[]string{`"gip-vote"`, "action 0", "recipient", `"after"`, "missing"}},
393		}
394		for _, tc := range corruptions {
395			t.Run(tc.name, func(t *testing.T) {
396				bad := filepath.Join(dir, "missing-"+strings.ReplaceAll(strings.ReplaceAll(tc.name, " ", "-"), "(", "")+".json")
397				if err := os.WriteFile(bad, tc.raw, 0o600); err != nil {
398					t.Fatal(err)
399				}
400				s, err := Open(bad)
401				if !errors.Is(err, ErrStateCorrupt) {
402					if s != nil {
403						s.Close()
404					}
405					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
406				}
407				for _, want := range tc.want {
408					if !strings.Contains(err.Error(), want) {
409						t.Fatalf("error %q does not locate %q", err.Error(), want)
410					}
411				}
412				// 缺损凭据不被删除或重写，原文件保持原样。
413				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
414					t.Fatalf("corrupt file was modified")
415				}
416			})
417		}
418	
419		// 打开后文件被换成缺损凭据：余额、提案、凭据查询与继续执行都失败，
420		// 不输出文件中其他正常记录的部分结果，也不改写原文件。
421		t.Run("all operations fail after corruption", func(t *testing.T) {
422			p := filepath.Join(dir, "swap.json")
423			if err := os.WriteFile(p, good, 0o600); err != nil {
424				t.Fatal(err)
425			}
426			s, err := Open(p)
427			if err != nil {
428				t.Fatal(err)
429			}
430			defer s.Close()
431			corrupt := mutateReceipt(0, 0, "treasury", "after", nil)
432			if err := os.WriteFile(p, corrupt, 0o600); err != nil {
433				t.Fatal(err)
434			}
435			if _, err := s.BalanceSnapshot(); !errors.Is(err, ErrStateCorrupt) {
436				t.Fatalf("BalanceSnapshot err=%v, want ErrStateCorrupt", err)
437			}
438			if _, _, err := s.Proposal("gip-1"); !errors.Is(err, ErrStateCorrupt) {
439				t.Fatalf("Proposal err=%v, want ErrStateCorrupt", err)
440			}
441			if _, _, err := s.Receipt("gip-vote"); !errors.Is(err, ErrStateCorrupt) {
442				t.Fatalf("Receipt err=%v, want ErrStateCorrupt", err)
443			}
444			if _, err := s.Receipts(); !errors.Is(err, ErrStateCorrupt) {
445				t.Fatalf("Receipts err=%v, want ErrStateCorrupt", err)
446			}
447			if _, err := s.Execute("gip-1", 500); !errors.Is(err, ErrStateCorrupt) {
448				t.Fatalf("Execute err=%v, want ErrStateCorrupt", err)
449			}
450			if got, _ := os.ReadFile(p); string(got) != string(corrupt) {
451				t.Fatalf("state file was modified by rejected operations")
452			}
453		})
454	}
455	
456	// TestTamperedReceiptBalancesRejectWithCause：凭据中资金库/收款账户的
457	// 前后余额被篡改时，整份状态判为损坏，错误沿用既有原因与动作位置，
458	// 原文件保持原样，不改成重算结果后继续提供查询。
459	func TestTamperedReceiptBalancesRejectWithCause(t *testing.T) {
460		dir := t.TempDir()
461		path := filepath.Join(dir, "treasury.json")
462		store, err := InitTreasury(path, 1000)
463		if err != nil {
464			t.Fatal(err)
465		}
466		mustRegister(t, store, "gip-1", 0,
467			"transfer:audits:250", "transfer:audits:100", "transfer:legal:50")
468		if _, err := store.Execute("gip-1", 0); err != nil {
469			t.Fatal(err)
470		}
471		store.Close()
472	
473		good, err := os.ReadFile(path)
474		if err != nil {
475			t.Fatal(err)
476		}
477		mutate := func(fn func(actions []any)) []byte {
478			var doc map[string]any
479			if err := json.Unmarshal(good, &doc); err != nil {
480				t.Fatal(err)
481			}
482			rcpt := doc["receipts"].([]any)[0].(map[string]any)
483			fn(rcpt["actions"].([]any))
484			raw, err := json.MarshalIndent(doc, "", "  ")
485			if err != nil {
486				t.Fatal(err)
487			}
488			return append(raw, '\n')
489		}
490		setField := func(actions []any, i int, side string, field string, value any) {
491			entry := actions[i].(map[string]any)[side].(map[string]any)
492			entry[field] = value
493		}
494		cases := []struct {
495			name string
496			raw  []byte
497			want string
498		}{
499			{"treasury-before", mutate(func(a []any) { setField(a, 1, "treasury", "before", 999) }),
500				"action 1 treasury before-balance mismatch"},
501			{"treasury-after", mutate(func(a []any) { setField(a, 1, "treasury", "after", 651) }),
502				"action 1 treasury after-balance mismatch"},
503			{"recipient-before", mutate(func(a []any) { setField(a, 1, "recipient", "before", 249) }),
504				"action 1 recipient before-balance mismatch"},
505			{"recipient-after", mutate(func(a []any) { setField(a, 1, "recipient", "after", 351) }),
506				"action 1 recipient after-balance mismatch"},
507			{"recipient-account", mutate(func(a []any) { setField(a, 0, "recipient", "account", "other") }),
508				"action 0 recipient before-balance mismatch"},
509			{"treasury-account", mutate(func(a []any) { setField(a, 0, "treasury", "account", "vault") }),
510				"action 0 treasury before-balance mismatch"},
511		}
512		for _, tc := range cases {
513			t.Run(tc.name, func(t *testing.T) {
514				bad := filepath.Join(dir, "tamper-"+tc.name+".json")
515				if err := os.WriteFile(bad, tc.raw, 0o600); err != nil {
516					t.Fatal(err)
517				}
518				s, err := Open(bad)
519				if !errors.Is(err, ErrStateCorrupt) {
520					if s != nil {
521						s.Close()
522					}
523					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
524				}
525				if !strings.Contains(err.Error(), tc.want) {
526					t.Fatalf("error %q missing %q", err.Error(), tc.want)
527				}
528				// 原文件保持原样，不被重算结果覆盖。
529				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
530					t.Fatalf("corrupt file was modified")
531				}
532			})
533		}
534	}
535	
536	// TestRegisteredAndVotedProposalsTransferIdentically：相同动作与起始余额下，
537	// 登记来源与投票通过来源的提案产生相同的资金变动与逐笔凭据，且已执行
538	// 提案再次执行仍返回首次凭据。
539	func TestRegisteredAndVotedProposalsTransferIdentically(t *testing.T) {
540		actions := []string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"}
541	
542		registered, _ := openTempStore(t, 1000)
543		defer registered.Close()
544		mustRegister(t, registered, "gip-r", 0, actions...)
545		rr, err := registered.Execute("gip-r", 0)
546		if err != nil {
547			t.Fatal(err)
548		}
549	
550		voted, _ := openTempStore(t, 1000)
551		defer voted.Close()
552		in := baseVoteInput("gip-v")
553		in.Actions = actions
554		in.StartAt, in.Deadline, in.TimelockEnd = 0, 1, 1
555		mustCreateVote(t, voted, in)
556		if _, err := voted.CastVote("gip-v", "alice", true, 0); err != nil {
557			t.Fatal(err)
558		}
559		if _, err := voted.TallyVote("gip-v", 1); err != nil {
560			t.Fatal(err)
561		}
562		vr, err := voted.Execute("gip-v", 1)
563		if err != nil {
564			t.Fatal(err)
565		}
566	
567		if len(rr.Actions) != len(vr.Actions) {
568			t.Fatalf("receipt action counts differ: %d vs %d", len(rr.Actions), len(vr.Actions))
569		}
570		for i := range rr.Actions {
571			// 两个来源的凭据只有动作原文（编号相同）与双方前后余额可比。
572			ra, va := rr.Actions[i], vr.Actions[i]
573			if ra.Action != va.Action || !reflect.DeepEqual(ra.Treasury, va.Treasury) ||
574				!reflect.DeepEqual(ra.Recipient, va.Recipient) || ra.Index != va.Index {
575				t.Fatalf("action %d differs by source:\nregistered=%+v\nvoted=%+v", i, ra, va)
576			}
577		}
578		for _, pair := range []struct {
579			name    string
580			store   *Store
581			receipt *Receipt
582			id      string
583		}{
584			{"registered", registered, rr, "gip-r"},
585			{"voted", voted, vr, "gip-v"},
586		} {
587			if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
588				t.Fatalf("%s treasury=%d, want 600", pair.name, bal)
589			}
590			if bal, _ := pair.store.Balance("audits"); bal != 350 {
591				t.Fatalf("%s audits=%d, want 350", pair.name, bal)
592			}
593			if bal, _ := pair.store.Balance("legal"); bal != 50 {
594				t.Fatalf("%s legal=%d, want 50", pair.name, bal)
595			}
596			// 再次执行返回首次凭据，不产生二次资金变动。
597			again, err := pair.store.Execute(pair.id, 99999)
598			if err != nil {
599				t.Fatalf("%s re-execute: %v", pair.name, err)
600			}
601			if again.Order != pair.receipt.Order || again.ExecutedAt != pair.receipt.ExecutedAt ||
602				!reflect.DeepEqual(again.Actions, pair.receipt.Actions) {
603				t.Fatalf("%s re-execute changed receipt:\nfirst=%+v\nagain=%+v", pair.name, pair.receipt, again)
604			}
605			if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
606				t.Fatalf("%s treasury changed on retry: %d", pair.name, bal)
607			}
608		}
609	}
